import json
with open('/app/resources/treasury_bulletin_1964_03.json') as f:
    data = json.load(f)
# Search recursively for anything with exchange/rate/currency/india/rupee
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if any(term in str(k).lower() for term in ['exchange', 'rate', 'currency', 'india', 'rupee', 'inr', 'foreign']):
                print(f'{path}.{k}: {str(v)[:200]}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')
search(data)
